import sys
from collections import deque

def read_input():
    input = sys.stdin.read().strip().split('\n\n')
    n, m, k = map(int, input[0].split())
    layers = [layer.split('\n') for layer in input[1:]]
    return n, m, k, layers

def parse_layers(n, m, k, layers):
    grid = [[[0 if layers[i][j][l] == '0' else 1 for l in range(k)] for j in range(m)] for i in range(n)]
    return grid

def bfs(grid, n, m, k, start):
    queue = deque([start])
    visited = set([start])
    while queue:
        x, y, z = queue.popleft()
        for dx, dy, dz in [(1, 0, 0), (0, 1, 0), (0, 0, 1)]:
            nx, ny, nz = x + dx, y + dy, z + dz
            if 0 <= nx < n and 0 <= ny < m and 0 <= nz < k and grid[nx][ny][nz] and (nx, ny, nz) not in visited:
                visited.add((nx, ny, nz))
                queue.append((nx, ny, nz))
    return visited

def find_critical_cpus(grid, n, m, k):
    critical_count = 0
    for x in range(n):
        for y in range(m):
            for z in range(k):
                if grid[x][y][z]:
                    grid[x][y][z] = 0
                    reachable_before = bfs(grid, n, m, k, (0, 0, 0))
                    grid[x][y][z] = 1
                    grid[x][y][z] = 0
                    reachable_after = bfs(grid, n, m, k, (0, 0 ,0))
                    grid[x][y][z] = 1
                    if len(reachable_before) > len(reachable_after):
                        critical_count += 1
    return critical_count

n, m, k, layers = read_input()
grid = parse_layers(n, m, k, layers)
print(find_critical_cpus(grid, n, m, k))
